import React, { useState } from "react";
import { Send } from "lucide-react";

export default function ChatInput({ onSend, disabled }) {
  const [value, setValue] = useState("");

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!value.trim()) return;
    onSend(value.trim());
    setValue("");
  };

  return (
    <form className="chat-input-row" onSubmit={handleSubmit} style={{ position: 'relative', display: 'flex', alignItems: 'center' }}>
      <input
        type="text"
        placeholder="Type your message..."
        value={value}
        onChange={(e) => setValue(e.target.value)}
        disabled={disabled}
        style={{ width: '100%', paddingRight: '48px', borderRadius: '24px', border: '1px solid #d1d5db', padding: '12px 48px 12px 16px', outline: 'none', transition: 'border-color 0.2s' }}
        onFocus={(e) => e.target.style.borderColor = '#3b82f6'}
        onBlur={(e) => e.target.style.borderColor = '#d1d5db'}
      />
      <button 
        className="btn-primary" 
        type="submit" 
        disabled={disabled || !value.trim()}
        style={{ 
          position: 'absolute', right: '4px', top: '50%', transform: 'translateY(-50%)', 
          borderRadius: '50%', width: '36px', height: '36px', padding: 0, 
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          backgroundColor: (!disabled && value.trim()) ? '#3b82f6' : '#9ca3af',
          border: 'none', cursor: (!disabled && value.trim()) ? 'pointer' : 'default', transition: 'background-color 0.2s'
        }}
      >
        <Send size={16} color="white" />
      </button>
    </form>
  );
}
